const BASE = 'https://n8n.checkintrust.com/webhook';
const EXT_TOKEN = 'edl_wh_7Kx2mPn9sRtL';
const DOCUSEAL_TOKEN = 'FtrjsZSaBdPdeZBTdhxbRTTXUMwV5gh6WFNqbBCbZTu';

const results = [];

async function t(name, fn) {
  try {
    await fn();
    results.push({ test: name, status: 'PASS' });
  } catch (e) {
    results.push({ test: name, status: 'FAIL', error: e.message });
  }
}

async function http(opts) {
  try {
    return await this.helpers.httpRequest(opts);
  } catch (e) {
    if (e.statusCode) return { _statusCode: e.statusCode };
    throw e;
  }
}
const h = http.bind(this);

// T1: Agent 0 — token valide
await t('Agent 0 — Token valide → liste', async () => {
  const data = await h({ method: 'GET', url: `${BASE}/edl-locataires?t=${EXT_TOKEN}` });
  if (!Array.isArray(data)) throw new Error('Pas un tableau');
  if (data.length === 0) throw new Error('Liste vide');
});

// T2: Agent 0 — sans token
await t('Agent 0 — Token manquant → 401', async () => {
  const r = await h({ method: 'GET', url: `${BASE}/edl-locataires`, ignoreHttpStatusErrors: true, returnFullResponse: true });
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T3: Agent 6 — token invalide
await t('Agent 6 — Token invalide → 401', async () => {
  const r = await h({ method: 'POST', url: `${BASE}/edl-secure`, body: { _token: 'BAD', meta: {}, pieces: {} }, headers: { 'Content-Type': 'application/json' }, ignoreHttpStatusErrors: true, returnFullResponse: true });
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T4: Agent 6 — schéma invalide
await t('Agent 6 — Schéma invalide → 401', async () => {
  const r = await h({ method: 'POST', url: `${BASE}/edl-secure`, body: { _token: EXT_TOKEN, meta: { type: 'INVALIDE', chambre: 999 }, pieces: {} }, headers: { 'Content-Type': 'application/json' }, ignoreHttpStatusErrors: true, returnFullResponse: true });
  if (r.statusCode !== 401) throw new Error(`Attendu 401, reçu ${r.statusCode}`);
});

// T5: DocuSeal — API accessible
await t('DocuSeal — API accessible', async () => {
  const data = await h({ method: 'GET', url: 'https://docuseal.checkintrust.com/api/templates?limit=1', headers: { 'X-Auth-Token': DOCUSEAL_TOKEN } });
  if (!data) throw new Error('Réponse vide');
});

const passed = results.filter(r => r.status === 'PASS').length;
const total = results.length;
return [{ json: { summary: `${passed}/${total} tests passés`, passed, total, allPassed: passed === total, results, timestamp: new Date().toISOString() } }];

